INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14688, 0, 0, 'frFR', 'Voilà une présentation bien peu convenable, Épouse-lance. Maintenant, qui est cet étranger dont j\'entends tant parler ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14688 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14688, 1, 0, 'frFR', 'Je vais vous rendre la chose aussi facile que possible. Venez simplement ici et mourez. C\'est tout ce que je demande pour vos nombreuses intrusions. Pour avoir souillé ce lieu de bataille exalté.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15263 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15263, 0, 1, 'frFR', 'À genoux, mortels ! L\'ère des ténèbres est proche.');
