INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15263, 1, 1, 'frFR', 'Misérables lâches ! Vous vous noierez dans des fleuves de sang !');
