INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15263, 1, 2, 'frFR', 'Les hurlements des mourants empliront l\'air. Une symphonie de terreur va commencer !');
