INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15690, 1, 1, 'frFR', 'Je vois que la subtilité du concept échappe à des primitifs tels que vous.');
