INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16577, 0, 0, 'frFR', 'Frères et sœurs, j\'ai vu la terre promise. J\'ai goûté à l\'énergie sublime. J\'ai connu la félicité, une félicité si absorbante et si totale que je me suis demandé si je n\'étais pas tombé sur les rêves des dieux !');
