DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17127 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17127, 0, 0, 'frFR', 'Prophète Velen');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17127 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17127, 1, 0, 'frFR', '… Merci, prophète. Vous nous avez rassurés. Je poursuivrai son œuvre en mémoire de Magtur.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17226 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17226, 3, 0, 'frFR', '%s détale en tentant d\'échapper à Twinkle.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17230 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17230, 0, 0, 'frFR', '%s regarde Viera Sunwhisper avec des yeux affamés.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 1, 0, 'frFR', 'Qu\'est-ce qui te prend ? Tu as failli me faire démasquer, idiot ! Je t\'avais dit de mettre la boussole et les cartes de navigation en lieu sûr, pas à la vue du premier imbécile venu.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 3, 0, 'frFR', 'Me calmer ? Tu sais ce que Kael\'thas fait à ceux qui échouent, Geezle ? Souffrance et douleur éternelles… Ne fais PAS tout rater, imbécile.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 4, 0, 'frFR', 'Nos éclaireurs de Brume-sang ont localisé notre contact. Cet imbécile de Velen va bientôt se retrouver exposé et sans défense, assez longtemps pour que nous frappions ! Maintenant, hors de ma vue avant que je te vaporise…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17257 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17257, 7, 0, 'frFR', 'Merci de m\'avoir libéré. Maintenant… mourez !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17318 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17318, 1, 0, 'frFR', 'Qu\'est-ce qui se passe, Spark ? Pourquoi as-tu demandé cette réunion ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17318 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17318, 2, 0, 'frFR', 'Du calme, Spark ! J\'ai tout sous contrôle. On va vider l\'Exodar de ses minerais sous leur nez, et ça fera de nous deux des gens très, très riches.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17318 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17318, 3, 0, 'frFR', 'Oui, chef. Ça ne se reproduira pas…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17392 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17392, 0, 0, 'frFR', '%s vous demande de le suivre.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17533 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17533, 2, 0, 'frFR', 'Le noir destin de ce jour pèse sur d\'autres jours. Ce n\'est que le début du malheur. D\'autres devront y mettre fin.');
