INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17842, 3, 0, 'frFR', 'Abandonnez tout espoir ! La Légion est revenue achever ce qu\'elle a commencé il y a tant d\'années. Cette fois, il n\'y aura pas d\'échappatoire !');
