INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17888, 2, 0, 'frFR', 'Implorez grâce ! Vos vies insignifiantes vous seront bientôt arrachées.');
