INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17968, 5, 0, 'frFR', 'Enfin, le moment est venu. Pleurez et lamentez-vous sur la fin de tout ce que vous avez connu et de tout ce qui aurait pu être ! Akmin-kurai !');
