INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18373, 0, 0, 'frFR', 'Vous avez profané le lieu de repos de nos ancêtres. Pour cet affront, il ne peut y avoir qu\'un seul châtiment. Il est juste que vous soyez venus dans un lieu des morts… car vous allez bientôt les rejoindre.');
