INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 7, 0, 'frFR', 'Venu de contrées inconnues : Skra\'gath ! $N pourra-t-$gil:elle; survivre au déferlement des énergies du Vide ?');
