INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 9, 0, 'frFR', 'Voici le moment que nous attendions tous ! Le champion Warmaul s\'apprête à faire $gsa:sa; première apparition au Cercle de sang depuis des semaines ! $N sera-t-$gil:elle; vaincu$g:e; aussi facilement que les autres adversaires du champion ? Nous allons voir…');
