INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22431, 7, 0, 'frFR', 'Arrière ! Je te repousse… corrupteur de la foi ! Artisan de la douleur ! Ne reviens pas, ou tu subiras le même sort qu\'aujourd\'hui !');
