INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 6, 0, 'frFR', 'Par les bananes fragiles de Brann ! Qu\'est-ce que c\'est ?! On… On dirait un tambour.');
