INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22464, 5, 0, 'frFR', 'Je ne crois pas que ça puisse battre la fois où il nous a raconté qu\'il avait entendu dire que le squelette du cousin d\'Arthas était gelé sous un glacier du Berceau-de-l\'Hiver. Celle-là, je ne te la pardonnerai jamais, Letoll. Franchement… le cousin d\'Arthas ?');
