INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23678, 0, 0, 'frFR', 'Je savais que Lurielle enverrait de l\'aide ! Merci, $gl\'ami:mon amie;, et transmettez aussi mes remerciements à Lurielle !');
