INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23768, 3, 0, 'frFR', 'J\'ai tant essayé de dire à Jim... de dire à n\'importe qui... qui était derrière tout ça, mais je n\'ai trouvé aucun moyen...');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23768 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23768, 4, 0, 'frFR', 'Merci de nous avoir aidés, et d\'avoir aidé Jim. Si vous le voyez, dites-lui que le petit Jimmy et moi l\'aimons, et que nous l\'attendons.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23768 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23768, 5, 0, 'frFR', 'Je ne sais pas quand nous reverrons papa, Jimmy, mais je sais qu\'il t\'aime et que tu lui manques beaucoup.');
