INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24711, 3, 0, 'frFR', 'Dommage que Coren soit mort. Si je pouvais lui acheter cette bière et la revendre – coupée d\'eau et remise en bouteille sous ma propre étiquette, bien sûr – je serais riche !');
