INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24711, 4, 2, 'frFR', 'Hé hé, encore un $r ! Bienvenue à ma célébration annuelle de la Fête des Brasseurs... maintenant, allez festoyer et boire un coup !');
