INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25322, 0, 0, 'frFR', 'Que les ancêtres vous viennent toujours en aide, $n, comme vous m\'êtes $gvenu:venue; en aide.');
