DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25504 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25504, 0, 0, 'frFR', 'L\'aura de mon père est très forte, il ne peut pas être loin. Seriez-vous $gun amour:une amie adorable; et repousseriez-vous les monstres qui errent dans la brume ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25504 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25504, 1, 0, 'frFR', 'Attention aux monstres ! Par où devrions-nous commencer ? Essayons par ici...');
