INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25773, 0, 4, 'frFR', 'Je suis de nouveau de chair et de sang ! Merci !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25814 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25814, 1, 1, 'frFR', 'Nous sommes les mécagnomes... toute résistance est inutile.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25814 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25814, 1, 2, 'frFR', 'La chair est faible. Nous allons vous rendre $gmeilleur, plus fort:meilleure, plus forte;... plus rapide.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26630 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26630, 0, 0, 'frFR', 'Plus de grunts, plus de glandes, plus de BOUFFE !');
