INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26631, 0, 0, 'frFR', 'Le froid que vous ressentez annonce votre perte !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26631 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
