DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 2, 1, 'frFR', 'Je sens de l\'incertitude en vous, et je ne m\'y fie pas, que vous soyez avec eux ou non. Si vous voulez mon augure pour les Kalu\'ak, vous devrez d\'abord faire vos preuves.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 4, 1, 'frFR', 'Bien joué, $n. Votre marque de respect est dûment notée. À présent, j\'ai des informations que vous devez transmettre aux Kalu\'ak.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 7 AND `ID` = 1 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 7, 1, 'frFR', 'Maintenant, repartez à la nage avec le savoir que je vous ai accordé. Faites ce que vous pouvez pour eux, $r.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26693 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26693, 6, 0, 'frFR', 'Brûlez-les jusqu\'à l\'os !');
