INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26796, 0, 0, 'frFR', 'Quoi ? Où est-ce que... ? Restez pas plantés là, les gars, TUEZ QUELQU\'UN !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26796 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26796, 1, 0, 'frFR', 'Là, on avance !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26796 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26796, 2, 0, 'frFR', 'C\'est tout ce que vous... avez ?');
