INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26817, 0, 1, 'frFR', 'Vous me renvoyez là-bas ?!');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27003 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27003, 2, 0, 'frFR', 'Ha ! Soit. Sonnez le cor d\'un chef magnataure au cercle de torches au sud du sanctuaire draconique d\'Azur. Faites la paix avec vos dieux... Grom\'thar viendra.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27199 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27199, 1, 0, 'frFR', 'Ahhh ! Qu\'est-ce qui m\'arrive, man ?');
