INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27355, 1, 0, 'frFR', 'Stupide $gpetit coursier:petite coursière;... vous allez mourir pour avoir interrompu mon travail !');
