INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27476, 0, 0, 'frFR', 'Je vous prie de m\'excuser, émissaire, mais le prince est absent pour une course. Qu\'est-ce qui vous amène en ce lieu désolé ?');
