DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27842 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27842, 0, 2, 'frFR', 'On aime les arbres, Fenrick. Ils nous offrent un couvert. Ils ne me laissent pas les abattre non plus.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27842 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27842, 0, 3, 'frFR', 'Je me demande combien de renforts devront être blessés avant qu\'on nous laisse abattre ces arbres idiots. Ils nous coûtent une fortune en chauves-souris. Je vais peut-être bricoler un harnais ou deux...');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27842 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27842, 1, 0, 'frFR', 'Arrrhhh... Gardes !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 2, 0, 'frFR', 'Attention... les voilà. Je vais t\'aider autant que je peux. Tenons-les juste à l\'écart du sablier !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 3, 0, 'frFR', 'Quoi qu\'il arrive, tu ne peux pas mourir, parce que ça voudrait dire que je cesserais d\'exister, pas vrai ? J\'étais déjà là quand j\'étais toi. Je suis complètement $gperdu:perdue; !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 8, 0, 'frFR', 'Quoi ? Je suis $gseul:seule; ici ? On a tous les deux quelque chose à y perdre, tu sais !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 12, 0, 'frFR', 'Adieu, $N. Garde-nous en vie et trouve-toi un meilleur équipement !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27990 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27990, 1, 0, 'frFR', 'D\'après votre description, je suis certain que le livre que j\'ai prêté à notre visiteur pourrait vous permettre d\'identifier facilement l\'arme.');
