INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 3, 0, 'frFR', 'Il y en a d\'autres juste devant, continuez !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 4, 0, 'frFR', 'On y est presque… encore un petit effort.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 5, 0, 'frFR', 'À part quelques rochers perdus lancés par ces géants, la voie devrait être libre… mais ça a l\'air d\'un sacré bazar, vu d\'en bas.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 8, 0, 'frFR', 'Nous approchons de Frosthold. Je vous serais très reconnaissant de me présenter au roi Stormeheart avant de partir. Je crois que nous avons tous deux une grande dette envers lui.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30292 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30292, 0, 0, 'frFR', 'Le flanc de cet ours est complètement gelé… réessayez.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 1, 0, 'frFR', 'Le roi-liche ne ressemble à aucun ennemi que vous ayez jamais affronté, généralissime. Vous l\'avez vaincu sur la terre sacrée de la chapelle de l\'Espoir de Lumière, mais vous foulez désormais son domaine.$B');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 2, 0, 'frFR', 'Vous ne pouvez pas gagner. Pas comme ça…$B');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 8, 0, 'frFR', 'Le roi-liche connaît vos limites, généralissime. Il sait que vous ne tirerez pas sur vos propres hommes. Ne comprenez-vous pas ? Lui n\'a aucune limite. Aucune règle à respecter. $B');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 9, 0, 'frFR', 'Alors vous avez perdu, généralissime.$B');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30399 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30399, 3, 0, 'frFR', 'N\'y songez même pas…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30404 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30404, 1, 0, 'frFR', 'Voici que le cauchemar est réel. Voici que le Dr Terrible est là. Pour vous faire trembler de peur. Pour faire plier le monde entier. Et je ne ressentirai… rien.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30404 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30404, 2, 0, 'frFR', 'JE ME RELÈVERAI ET CE JOUR-LÀ, J\'AURAI MA VENGEANCE !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 0, 0, 'frFR', 'Par tous les dieux… ce n\'est pas possible… Muradin ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 1, 0, 'frFR', 'Allons, mon gars, y a pas d\'erreur possible, c\'est bien toi. Tu reconnais pas ton p\'tit frère ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 3, 0, 'frFR', 'Et comment ! Magni sera si heureux de te voir, lui aussi ! Il n\'a reçu que de mauvaises nouvelles depuis bien longtemps, mais ça change tout !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 4, 0, 'frFR', 'Il est ici, en Norfendre, mon frère, à ta recherche. Un voyant de Garde-Hiver lui a fait savoir que tu n\'étais pas mort, et il a quitté Forgefer sur-le-champ pour venir te trouver.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 4, 0, 'frFR', 'Je… j\'sais pas, Brann. J\'suis là d\'puis longtemps… tout c\'qui m\'reste de ma vie d\'avant, c\'est des éclairs et des cauchemars.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 6, 0, 'frFR', 'Magni ! Pardonne-moi, les souvenirs me r\'viennent lentement, mon frère.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 11, 0, 'frFR', 'Non… non, elles le f\'ront pas. Mais j\'peux réparer ça. J\'le dois. J\'vais aller chercher le gamin. J\'lui f\'rai payer tout c\'qu\'il a fait.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 13, 0, 'frFR', 'Va, Brann. Rapporte-nous un récit épique quand on se reverra. Adieu pour l\'instant, mes frères…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30411 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30411, 0, 0, 'frFR', 'Écoutez, Lagnus, je vous tiens pour un homme capable, mais ma patience a des limites. Je sais que Muradin est ici. Pouvez-vous me conduire à lui, oui ou non ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30411 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30411, 3, 0, 'frFR', 'On dirait bien ! Et toi non plus, t\'as pas perdu de muscles. Te souviens-tu de ce qui s\'est passé, Muradin ? Le destin a mal tourné en ton absence.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30840 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30840, 2, 2, 'frFR', 'Lève-toi, Fondu !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30840 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30840, 3, 3, 'frFR', 'On en a fini ici. Je m\'en vais.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30951 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30951, 0, 0, 'frFR', '%s entre en frénésie !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31099 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31099, 1, 0, 'frFR', 'Comment as-tu pu me laisser comme ça ! Je te déteste ! =*(');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31099 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31099, 1, 1, 'frFR', '…non… comment as-tu pu me laisser mourir, $N ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 4, 0, 'frFR', 'Je vous dérange ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 5, 0, 'frFR', 'Tremblez et mourez !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 6, 0, 'frFR', 'Le monde a oublié ce qu\'est la vraie magie ! Que ceci vous le rappelle !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31277 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31277, 0, 0, 'frFR', 'ASSEZ ! Vous, minuscules insectes, n\'êtes pas dignes de combattre en ce lieu sacré !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32236 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32236, 0, 3, 'frFR', 'NOOOOOON');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32239 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32239, 6, 0, 'frFR', 'C\'est possible, mais je n\'ai pas besoin de me tenir en terre sacrée pour transpercer ton cœur désincarné avec le Porte-cendres.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 1, 0, 'frFR', 'Contemplez la puissance des tempêtes et désespérez !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 3, 0, 'frFR', 'Commencez-vous à regretter votre intrusion ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32871 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32871, 18, 0, 'frFR', 'Début de la liaison montante : code de réponse : « Oméga ». Réorigination planétaire demandée.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33134 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33134, 0, 0, 'frFR', 'Aidez-moi ! Je vous en prie, débarrassez-moi d\'eux !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33134 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33134, 3, 0, 'frFR', 'Impuissants à agir…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33178 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33178, 2, 0, 'frFR', 'Mettons fin une fois pour toutes à la menace des Brisépieux. Sentinelles, attaquez maintenant !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33220 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33220, 1, 0, 'frFR', 'Et maintenant, je dois retourner dans les eaux du lac.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33440 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33440, 0, 0, 'frFR', 'J\'y vais ! Ouvrez l\'œil…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33440 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33440, 1, 0, 'frFR', 'J\'ai un mauvais pressentiment…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33515 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33515, 2, 0, 'frFR', 'Auriaya hurle de douleur.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 9, 0, 'frFR', 'Peut-être que vous dormez, m\'sieur Grand Ancien ? Nous tenir debout. Doit être dur, travail de Grand Ancien, ramasser tous les trucs brillants qu\'on laisse pour vous.');
