INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33889, 1, 0, 'frFR', 'Quand tout ça sera fini, vous devriez peut-être travailler votre discrétion…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33972 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33972, 0, 0, 'frFR', 'Utilisez Brise-bouclier sur une cible de charge$B|TInterface\\Icons\\ability_warrior_shieldbreak.blp:32|t$BEnchaînez avec Charge tant que la cible est vulnérable$B|TInterface\\Icons\\ability_mount_charger.blp:32|t');
