INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33973, 0, 0, 'frFR', 'Activez Défendre$B|TInterface\\Icons\\ability_warrior_shieldmastery.blp:32|t$BPuis utilisez Estoc sur une cible de mêlée$B|TInterface\\Icons\\inv_sword_65.blp:32|t');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33974 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33974, 0, 0, 'frFR', 'Utilisez Brise-bouclier sur une cible à distance$B|TInterface\\Icons\\ability_warrior_shieldbreak.blp:32|t$BPuis utilisez Brise-bouclier tant que la cible est sans défense$B|TInterface\\Icons\\ability_warrior_shieldbreak.blp:32|t');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34416 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34416, 1, 0, 'frFR', 'Qui ose s\'opposer à la reine Azshara ? Vous supplierez bientôt qu\'on vous accorde une mort rapide.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34416 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34416, 2, 0, 'frFR', 'Ah… Malfurion Hurlorage. J\'espérais vous occuper un peu plus longtemps. Mon but était de vous tenir éloigné d\'Hyjal pendant que mes alliés attaquaient. Il semblerait que j\'aie réussi.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34416 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34416, 3, 0, 'frFR', 'Je n\'ai nul besoin de vous combattre, car il semble que j\'aie déjà gagné. Vous ne pouvez pas à la fois arrêter notre attaque sur Sombrivage et sauver Hyjal.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34780 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34780, 5, 0, 'frFR', '$n subit |cFF00FFFFIncinérer la chair !|r Soignez-$gle:la; !');
