INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34928, 1, 0, 'frFR', 'Eh bien, commençons.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34928 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34928, 5, 0, 'frFR', 'Même le plus sombre des souvenirs s\'efface lorsqu\'on l\'affronte.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34957 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34957, 3, 0, 'frFR', 'C\'était quoi, ce truc, ma jolie ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34959 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34959, 3, 0, 'frFR', 'Pourquoi le sol tremble-t-il, $n ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 5, 0, 'frFR', 'Même les plus puissants serviteurs du roi-liche ne peuvent résister à l\'Alliance ! Gloire à nos vainqueurs !');
