INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (44058, 3, 0, 'frFR', 'Tout le monde me demande : « Horton, pourquoi tu montes et tu descends la rivière en bateau ? » Et je leur réponds : « Et vous, pourquoi pas ? »… C\'est en général là que je suis à court de réparties.');
