INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (44058, 4, 0, 'frFR', 'Nous approchons de votre arrêt. Suivez la route plein ouest pour rejoindre l\'avant-poste de Nozzlepot.');
