UPDATE `creature_text` SET `Text` = 'Thank you so much, brave heroes! I will tell stories of you! Of $n the Mighty! And Ken-Ken the Fearless!' WHERE `CreatureID` = 57457 AND `GroupID` = 0 AND `ID` = 14 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '5468616E6B20796F7520736F206D7563682C206272617665206865726F65732120492077696C6C2074656C6C2073746F72696573206F6620796F7521204F66203C6E616D653E20746865204D69676874792120416E64204B656E2D4B656E2074686520466561726C65737321';
