INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (57457, 0, 14, 'frFR', 'Merci infiniment, braves héros ! Je raconterai vos exploits ! Ceux de $n le Puissant ! Et de Ken-Ken l\'Intrépide !');
