INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (60536, 1, 0, 'frFR', 'Mon père avait vu ce jour dans les eaux. Il m\'avait dit que je serais vaincu, mais j\'ai refusé de le croire.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 60539 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (60539, 1, 0, 'frFR', 'Tukka-Tuk bien triste d\'avoir perdu contre minus $n. Tukka-Tuk va aller regarder l\'horizon et réfléchir à la vie.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 60543 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (60543, 1, 0, 'frFR', 'Oui… oui, je crois que vous ferez l\'affaire. Nous nous reverrons bientôt, $n.');
