INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (60730, 0, 0, 'frFR', 'Merci de m\'avoir libéré, mon frère. Je ne peux pas te laisser combattre seul.');
