INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (64528, 1, 0, 'frFR', 'Il y a dix mille ans, le dernier empereur pandaren est venu chercher mes conseils. Lui aussi était en proie au conflit. Voyons si vous avez raison, Taran. Voyons comment cet étranger fait face aux tourments de l\'âme.');
