INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (64528, 4, 0, 'frFR', 'Eh bien, celui-ci a bel et bien prouvé sa maîtrise de la colère. Entre les paroles du jeunot et les actes de ce héros, je crois comprendre. Ceux qui viennent d\'au-delà des brumes sont endurcis par la bataille. Ils portent des cicatrices, certes, mais ils ont beaucoup appris. Je leur fais confiance.');
