INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (64528, 5, 0, 'frFR', 'C\'est décidé. J\'ouvrirai les portes. Le val de l\'Éternel printemps sera ouvert à tous.');
