UPDATE `creature_text` SET `Text` = 'Go see if you can find a frost mage to help us, $n. If we can get our quenching trough cool enough, we can perform this leysmithing technique.' WHERE `CreatureID` = 92183 AND `GroupID` = 0 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '476F2073656520696620796F752063616E2066696E6420612066726F7374206D61676520746F2068656C702075732C203C6E616D653E2E2049662077652063616E20676574206F7572207175656E6368696E672074726F75676820636F6F6C20656E6F7567682C2077652063616E20706572666F726D2074686973206C6579736D697468696E6720746563686E697175652E';
