INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (92183, 0, 0, 'frFR', 'Allez voir si vous pouvez trouver un mage de givre pour nous aider, $n. Si nous parvenons à refroidir suffisamment notre bac de trempe, nous pourrons employer cette technique de forge tellurique.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 92195 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (92195, 2, 2, 'frFR', 'Ne perdez pas espoir, %s. Continuez à moudre, et examinez vos encres pour y déceler des propriétés inhabituelles. Ensemble, vous et \r\nmoi pourrons peut-être combler les lacunes de ce livre.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 92195 AND `GroupID` = 12 AND `ID` = 12 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (92195, 12, 12, 'frFR', 'Je suppose que je dois bien une faveur à ce fanfaron. Heureusement pour vous, la traduction est ma spécialité !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 92195 AND `GroupID` = 13 AND `ID` = 13 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (92195, 13, 13, 'frFR', 'C\'est une écriture vrykule ancienne, propriété d\'une certaine « Svena ». Une trouvaille rare et fascinante, en vérité. Dites à Deucus qu\'il a désormais une dette envers MOI !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 92242 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (92242, 0, 0, 'frFR', 'J\'informerai les autres de votre don, $n. Merci encore.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 92243 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (92243, 0, 0, 'frFR', 'C\'est tout ce que vous savez faire ? Il va falloir faire mieux que ça. Ça ne marchera pas comme ça.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 92458 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (92458, 2, 2, 'frFR', 'Je suppose que je devrais débarrasser ce fatras pour faire de la place aux nouveaux instruments.');
