INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (92458, 8, 8, 'frFR', 'Veillez juste à ce qu\'$Gil:elle; ne mette pas le bazar sur ma table d\'alchimie !');
