DELETE FROM `creature_text_locale` WHERE `CreatureID` = 97166 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (97166, 0, 0, 'frFR', 'La val\'kyr approche ! Nous devons l\'accueillir avec respect. Sortez, héros !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 97748 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (97748, 2, 0, 'frFR', 'Ça s\'annonce plutôt bien jusqu\'ici. Ne vous arrêtez pas maintenant, $n.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 97748 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (97748, 3, 0, 'frFR', 'J\'ai presque fini, je vous le jure.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 97756 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (97756, 1, 1, 'frFR', 'Dommage que ce soit votre corps qu\'il devra racler sur le sol des égouts !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 97762 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (97762, 0, 0, 'frFR', 'Servez-vous des livres posés sur la table derrière moi pour écrire votre histoire.');
