DELETE FROM `creature_text_locale` WHERE `CreatureID` = 98224 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (98224, 0, 0, 'frFR', 'Très bien, soit. Je m\'excuse pour les éventuelles déchirures ou traces de griffes sur le papier.');
DELETE FROM `creature_text` WHERE `CreatureID` = 99026 AND `GroupID` = 3 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '4D79205869616F68656E67204C652077656E74206F757420666F7220686572206669727374207368616D616E20747269616C202E2E2E2049276D20736F20776F72726965642061626F7574206865722120466972612C20686F772064696420796F7520736574746C65207768656E205465726E2077656E7420746F2074686520747269616C3F';
DELETE FROM `creature_text` WHERE `CreatureID` = 99026 AND `GroupID` = 3 AND `ID` = 1 AND `Text` = 'My Xiaoheng Le went out for her first shaman trial ... I\'m so worried about her! Fira, how did you settle when Tern went to the trial?';
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextID`, `MinTimer`, `MaxTimer`, `SpellID`, `comment`) VALUES (99026, 3, 1, 'My Xiaoheng Le went out for her first shaman trial ... I\'m so worried about her! Fira, how did you settle when Tern went to the trial?', 12, 0, 100, 1, 0, 0, 0, 9737, 9737, 0, 'çˆæ‹‰â€§æœ¨æ©‹ to Player');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99026 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99026, 3, 1, 'frFR', 'Ma Xiaoheng Le est partie pour sa première épreuve de chamane… Je m\'inquiète tellement pour elle ! Fira, comment as-tu gardé ton calme pendant l\'épreuve de Tern ?');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99028 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99028, 3, 0, 'frFR', 'Ne t\'inquiète pas trop. Jara et Henle sont de jeunes taurens talentueux, tout comme Tern. Elle avait les qualités requises pour l\'épreuve, et je pense qu\'elle peut la réussir.');
UPDATE `creature_text` SET `Text` = '$c $n, We urgently need to talk!' WHERE `CreatureID` = 99343 AND `GroupID` = 1 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '7C332D36282463742920246E2C20576520757267656E746C79206E65656420746F2074616C6B21';
