INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99343, 1, 0, 'frFR', '$c $n, nous devons parler de toute urgence !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99420 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99420, 0, 0, 'frFR', 'Vous venez ici, à cette heure, et demandez une chose pareille ? Laissez-moi tranquille, chasseur !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99517 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99517, 1, 0, 'frFR', 'Un étranger venu d\'une autre terre est venu honorer mon nom ? Cela me réjouit. Le savoir que je dois vous transmettre est celui de la totalité.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99534 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99534, 1, 0, 'frFR', 'Votre respect est humblement reçu, worgen. La sagesse que j\'accorde à ceux qui m\'honorent est la frugalité.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99534 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99534, 3, 0, 'frFR', 'Bien des petites choses finissent toujours par former quelque chose de plus grand, et souvent tout aussi fort.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99538 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99538, 2, 0, 'frFR', 'Les méthodes qui servent à façonner le cuir peuvent aussi servir à façonner l\'esprit et la pensée.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99538 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99538, 3, 0, 'frFR', 'La confiance en vos conclusions vous donnera de la force, mais la souplesse dans vos actes vous accordera la sagesse.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99570 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99570, 1, 0, 'frFR', 'Que voulez-vous, chétive créature ? Une leçon ? D\'accord, je vais vous en donner une.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99689 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99689, 0, 0, 'frFR', 'Bien, $n. Je suis votre ombre à partir de maintenant. Essayez de ne pas nous faire tuer.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 99958 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (99958, 0, 0, 'frFR', 'Je ne l\'ai pas vu, mais c\'est bien lui que nous cherchons. Les kvaldirs du coin ont peur d\'un énorme félin qui s\'est installé dans les marais. Ils ont dressé des pierres de guet qui barrent le chemin, non seulement jusqu\'à elle, mais aussi jusqu\'à nous.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 100235 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (100235, 13, 0, 'frFR', 'Je te vengerai. Nous devons aller jusqu\'au bout. Suivez la piste du monstre.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 100235 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (100235, 21, 0, 'frFR', 'Je… suis arrivée au bout de la piste… ensuite, vous devrez continuer $gseul:seule;.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 100727 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (100727, 4, 0, 'frFR', 'C\'était génial !! J\'étais genre : « Oh non ! » Et toi, t\'étais genre : « T\'inquiète, laisse-moi faire ! »');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 100884 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (100884, 2, 0, 'frFR', 'Je ne l\'ai pas revu depuis, cela dit. J\'espère qu\'il n\'a pas succombé au même mal que les harpies.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 101846 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (101846, 4, 0, 'frFR', 'Apportez-moi d\'autres ingrédients, maître $p. Viande, poisson, sang… tout ce que vous trouverez là-dehors, dans la nature effrayante. Je vous aiderai à les transformer en plats délicieux !');
DELETE FROM `creature_text` WHERE `CreatureID` = 102252 AND `GroupID` = 1 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '4920666F756E642061207761636B7920646F672120546F2074686520776561706F6E21';
