DELETE FROM `creature_text_locale` WHERE `CreatureID` = 102252 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (102252, 1, 1, 'frFR', 'J\'ai trouvé un chien loufoque ! Aux armes !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 102824 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (102824, 3, 0, 'frFR', 'Cela fait bien trop longtemps, $p. Bien trop longtemps.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 103344 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (103344, 2, 0, 'frFR', 'Je vais vous briser comme du petit bois.');
DELETE FROM `creature_text` WHERE `CreatureID` = 103488 AND `GroupID` = 3 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '457863656C6C656E7420776F726B21204576656E206E6F772074686520666F756C206372656570206F6620746865204E696768746D6172652068617320626567756E20746F20666164652E';
DELETE FROM `creature_text` WHERE `CreatureID` = 103488 AND `GroupID` = 3 AND `ID` = 1 AND `Text` = 'Excellent work! Even now the foul creep of the Nightmare has begun to fade.';
