DELETE FROM `creature_text_locale` WHERE `CreatureID` = 103488 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (103488, 3, 1, 'frFR', 'Excellent travail ! Déjà, l\'ignoble emprise du Cauchemar commence à s\'estomper.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 103489 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (103489, 3, 0, 'frFR', 'Je vais retirer ces lianes cauchemardesques de notre chemin, mais la source de gangrène qui les a fait naître se trouve ailleurs. $n, trouvez cette source et détruisez-la !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 103568 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (103568, 1, 0, 'frFR', 'J\'ai fui Val\'sharah quand Ysera a attaqué le temple. J\'ai eu beaucoup de chance de croiser Mitandros en chemin.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 104948 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (104948, 1, 0, 'frFR', 'Le chaos… dévore !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 104948 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (104948, 4, 0, 'frFR', 'Pas pu protéger l\'archidruide… trop nombreux !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 104950 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (104950, 3, 0, 'frFR', 'Argh ! Il part avec le seigneur du Cauchemar… vous ne pouvez plus l\'arrêter maintenant !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 104951 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (104951, 1, 0, 'frFR', 'Vous courez à votre mort, imbécile !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 104951 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (104951, 2, 0, 'frFR', 'Hahaha… ! Mon travail est accompli. Allez, le maître attend !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 104951 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (104951, 4, 0, 'frFR', 'Xavius le tient déjà ! Vous arrivez bien trop tard !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 105760 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (105760, 0, 0, 'frFR', 'Mais oui, nous en avons. Il y en a sur ce coffre, là-bas. Mais nous sommes à court, alors n\'en prenez pas trop, s\'il vous plaît.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 106087 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (106087, 10, 0, 'frFR', 'Cibles en évitement !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 106087 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (106087, 11, 0, 'frFR', 'Plateforme en évitement !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 106610 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (106610, 0, 0, 'frFR', 'Calydus sait où c\'est ! Calydus peut aider !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 106749 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (106749, 0, 0, 'frFR', 'Quoi encore ?! Un jour, je me libérerai de votre emprise et… attendez… vous n\'êtes pas mon maître.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 106750 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (106750, 0, 0, 'frFR', 'Hmpf… très bien. Venez à Felsoul Hold si vous croyez vraiment pouvoir me libérer. Vous avez intérêt à être à la hauteur, sinon vous me rejoindrez dans le tourment éternel !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 107314 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (107314, 0, 0, 'frFR', 'Celui que vous cherchez portait une étincelle de Tyr. Une toute petite, mais elle l\'a attiré ici… et en a attiré d\'autres jusqu\'à lui.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 107314 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (107314, 1, 0, 'frFR', 'L\'étincelle lui a montré une vision. Quand Tyr a perdu sa main, les drakes ont tenté de l\'aider, mais seul un autre gardien pouvait le sauver. Un gardien en particulier.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 107314 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (107314, 2, 0, 'frFR', 'Votre ami a appris l\'existence du compagnon de Tyr, condamné à errer à jamais sur le chemin des titans. Il a poursuivi le géant de pierre et l\'a rattrapé au bord d\'un gouffre… au moment même où son propre destin le rattrapait.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 107622 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (107622, 2, 0, 'frFR', 'Ha ! Vous ne lui ressemblez pas ! Bon, voyons voir…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 107622 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (107622, 3, 0, 'frFR', 'Enfin, vous avez son sceau. Comment l\'avez-vous obtenu ? Bon, je crois que je n\'ai pas le choix.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 107622 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (107622, 4, 0, 'frFR', 'Dites à ce balourd que s\'il veut reprendre là où on s\'était arrêtés, je suis là tous les jours, à toute heure !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 107683 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (107683, 0, 0, 'frFR', 'Imbéciles. Vos âmes pathétiques alimenteront la venue de la Légion !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 107683 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (107683, 1, 0, 'frFR', 'Reculez, racaille $r. Vous ignorez tout des forces que vous défiez.');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 107736 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (107736, 0, 0, 'frFR', 'Oui, oui ! Ils se rapprochent à chaque instant !');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 107736 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (107736, 5, 0, 'frFR', 'Usurpateur. Voleur. Scélérat ! Vous ne nous priverez pas de notre glorieux destin !');
