INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (108097, 1, 0, 'frFR', 'La suite va être compliquée. Nous devrons commencer le rituel ici pour attirer toute cette puissance. Pendant ce temps, nous serons très probablement attaqués.');
